import type { Project, StatusDef, UnitDef } from "@gml/core";
import data from "./hsr-enemies.generated.json";

/** Generated by scripts/build-hsr-encounters.mjs (data/reference/hsr/pack.json). */
export interface HsrEncounter {
  id: string;
  name: string;
  kind: "普通" | "精英" | "首領";
  description: string;
  /** Starting enemy unit ids, in line-up order (may repeat). */
  enemies: string[];
  /** Every unit the encounter needs, including summons. */
  units: string[];
  /** Status ids those units apply. */
  statuses: string[];
}

interface Generated {
  source: { text: string; version: string };
  levels: number[];
  defaultLevel: number;
  toughnessScale: number;
  encounters: HsrEncounter[];
  statuses: unknown[];
  units: Record<string, unknown[]>;
}
const gen = data as unknown as Generated;

export const hsrEncounters: HsrEncounter[] = gen.encounters;
export const hsrLevels: number[] = gen.levels;
export const hsrDefaultLevel: number = gen.defaultLevel;
export const hsrEnemySource: string = gen.source.text;
export const hsrToughnessScale: number = gen.toughnessScale;
export const HSR_ENEMY_PREFIX = "hsre_";

const clone = <T,>(x: T): T => JSON.parse(JSON.stringify(x)) as T;

/**
 * Puts an encounter's enemies (at one of the shipped levels) into the project and makes it the current line-up.
 * Earlier hsre_ enemies and statuses are removed first, so repeated picks never pile up; units with the same id
 * are replaced, which resets any edits made to them.
 */
export function applyHsrEncounter(draft: Project, enc: HsrEncounter, level: number): boolean {
  const pool = gen.units[String(level)] as UnitDef[] | undefined;
  if (!pool) return false;
  const units = enc.units.map((id) => pool.find((u) => u.id === id));
  if (units.some((u) => !u)) return false;
  const b = draft.battle;
  b.units = b.units.filter((u) => !(u.team === "enemy" && u.id.startsWith(HSR_ENEMY_PREFIX)));
  b.statuses = b.statuses.filter((s) => !s.id.startsWith(HSR_ENEMY_PREFIX));
  for (const u of units) b.units.push(clone(u!));
  for (const id of enc.statuses) {
    const s = (gen.statuses as StatusDef[]).find((x) => x.id === id);
    if (s) b.statuses.push(clone(s));
  }
  b.encounter.enemies = [...enc.enemies];
  return true;
}

/** The shipped encounter currently in the line-up (with its level), or null for any other enemy set. */
export function currentHsrEncounter(project: Project): { encounter: HsrEncounter; level: number } | null {
  const b = project.battle;
  const key = b.encounter.enemies.join();
  const encounter = hsrEncounters.find((e) => e.enemies.join() === key);
  if (!encounter) return null;
  const first = b.units.find((u) => u.id === encounter.enemies[0]);
  if (!first) return null;
  return { encounter, level: first.stats.level ?? gen.defaultLevel };
}
